{"output":"1\t#!/usr/bin/env bash\n2\t# =============================================================================\n3\t# lib.sh — deploy-bundle 子脚本公共库\n4\t# -----------------------------------------------------------------------------\n5\t# 由 installer.sh 或各 stage 子脚本 source。\n6\t# 不直接执行。\n7\t# =============================================================================\n8\t\n9\t# 防止重复 source\n10\t[[ -n \"${_DEPLOY_BUNDLE_LIB_LOADED:-}\" ]] && return 0\n11\t_DEPLOY_BUNDLE_LIB_LOADED=1\n12\t\n13\tset -Eeuo pipefail\n14\t\n15\t# -----------------------------------------------------------------------------\n16\t# 常量（从 /opt/deploy-bundle.env 覆盖）\n17\t# -----------------------------------------------------------------------------\n18\t: \"${DEPLOY_BUNDLE_ROOT:=/opt/deploy-bundle}\"\n19\t: \"${DEPLOY_MODE:=interactive}\"\n20\t: \"${DEPLOY_STAGE:=all}\"\n21\t: \"${DEPLOY_LANG:=zh-CN}\"\n22\t: \"${MYSQL_PORT:=3306}\"\n23\t# MySQL root/admin 固定密码（可用 --mysql-password 或环境变量覆盖）\n24\t# 注意：该值会写入 /opt/deploy-bundle.env（600 权限），不要提交到公共仓库\n25\t: \"${MYSQL_ROOT_PW:=ywj02402570687}\"\n26\t: \"${TOMCAT_PORT:=8080}\"\n27\t: \"${SKIP_MYSQL:=0}\"\n28\t: \"${SKIP_TOMCAT:=0}\"\n29\t: \"${SKIP_SELINUX:=0}\"\n30\t: \"${SKIP_FIREWALL:=0}\"\n31\t: \"${SKIP_APP:=0}\"\n32\t: \"${TARGET_BASE:=/opt}\"\n33\t: \"${TARGET_JDK_DIR:=/opt/jdk}\"\n34\t: \"${TARGET_MYSQL_DIR:=/opt/mysql}\"\n35\t: \"${TARGET_TOMCAT_DIR:=/opt/tomcat}\"\n36\t: \"${TARGET_DATA_DIR:=/var/lib/mysql}\"\n37\t: \"${TARGET_BACKUP_ROOT:=/opt/deploy-bundle-backups}\"\n38\t: \"${LOG_FILE:=/var/log/installer_lib.log}\"\n39\t: \"${REPORT_FILE:=/var/log/installer_report.txt}\"\n40\t: \"${PKG_DIR:=${DEPLOY_BUNDLE_ROOT}/packages}\"\n41\t: \"${CFG_DIR:=${DEPLOY_BUNDLE_ROOT}/configs}\"\n42\t: \"${SCRIPTS_DIR:=${DEPLOY_BUNDLE_ROOT}/scripts}\"\n43\t: \"${DETECT_CACHE:=/tmp/deploy-bundle.detect}\"\n44\t\n45\t# 退出码\n46\tEX_OK=0\n47\tEX_USAGE=1\n48\tEX_SYS=2\n49\tEX_DEPS=3\n50\tEX_SELINUX=4\n51\tEX_NET=5\n52\tEX_CLEANUP=6\n53\tEX_HEALTH=7\n54\t\n55\t# -----------------------------------------------------------------------------\n56\t# 日志\n57\t# -----------------------------------------------------------------------------\n58\tlog() {\n59\t    local level=\"$1\"; shift\n60\t    local ts; ts=\"$(date '+%Y-%m-%d %H:%M:%S')\"\n61\t    local line=\"[${ts}] [${level}] $*\"\n62\t    printf '%s\\n' \"${line}\" >&2\n63\t    if [[ -n \"${LOG_FILE}\" ]]; then\n64\t        printf '%s\\n' \"${line}\" >> \"${LOG_FILE}\" 2>/dev/null || true\n65\t    fi\n66\t}\n67\tinfo() { log \"INFO\"  \"$@\"; }\n68\twarn() { log \"WARN\"  \"$@\"; }\n69\terr()  { log \"ERROR\" \"$@\" >&2; }\n70\tok()   { log \"OK\"    \"$@\"; }\n71\t\n72\tdie() {\n73\t    local code=\"$1\"; shift\n74\t    err \"$*\"\n75\t    exit \"${code}\"\n76\t}\n77\t\n78\t# -----------------------------------------------------------------------------\n79\t# 干跑模式（只打印，不执行）\n80\t# -----------------------------------------------------------------------------\n81\tis_dry_run() { [[ \"${DEPLOY_MODE}\" == \"dry-run\" ]]; }\n82\tDRY_RUN_CMD=()\n83\tis_dry_run && DRY_RUN_CMD=(echo \"[DRY-RUN]\")\n84\t\n85\trun() {\n86\t    # 干跑：只打印命令，不执行\n87\t    if is_dry_run; then\n88\t        echo \"[DRY-RUN] $*\" >&2\n89\t        return 0\n90\t    fi\n91\t    \"$@\"\n92\t}\n93\t\n94\t# -----------------------------------------------------------------------------\n95\t# 探测结果加载\n96\t# -----------------------------------------------------------------------------\n97\tload_detect_cache() {\n98\t    if [[ -f \"${DETECT_CACHE}\" ]]; then\n99\t        # shellcheck disable=SC1090\n100\t        source \"${DETECT_CACHE}\"\n101\t        info \"已加载探测缓存：${DETECT_CACHE}\"\n102\t        info \"  OS=${OS_ID:-?} ${OS_VERSION:-?} family=${OS_FAMILY:-?} arch=${ARCH:-?} glibc=${GLIBC_VERSION:-?}\"\n103\t        info \"  pkg_mgr=${PKG_MGR:-?} systemd=${HAVE_SYSTEMD:-0} selinux=${HAVE_SELINUX:-0} apparmor=${HAVE_APPARMOR:-0}\"\n104\t        info \"  firewalld=${HAVE_FIREWALLD:-0} ufw=${HAVE_UFW:-0} iptables=${HAVE_IPTABLES:-0}\"\n105\t    else\n106\t        warn \"未找到探测缓存：${DETECT_CACHE}，请先运行 precheck.sh\"\n107\t    fi\n108\t}\n109\t\n110\trequire_detect() {\n111\t    [[ -f \"${DETECT_CACHE}\" ]] || die \"${EX_SYS}\" \"缺少探测结果，请先运行：bash ${SCRIPTS_DIR}/precheck.sh\"\n112\t}\n113\t\n114\trequire_root() {\n115\t    [[ \"${EUID}\" -eq 0 ]] || die \"${EX_USAGE}\" \"需要 root 权限，请用 sudo 运行\"\n116\t}\n117\t\n118\t# -----------------------------------------------------------------------------\n119\t# 工具函数\n120\t# -----------------------------------------------------------------------------\n121\thave_cmd() { command -v \"$1\" >/dev/null 2>&1; }\n122\t\n123\t# 备份目录创建\n124\tensure_backup_dir() {\n125\t    local sub=\"${1:-generic}\"\n126\t    local ts; ts=\"$(date +%Y%m%d_%H%M%S)\"\n127\t    local dir=\"${TARGET_BACKUP_ROOT}/${ts}/${sub}\"\n128\t    mkdir -p \"${dir}\"\n129\t    printf '%s' \"${dir}\"\n130\t}\n131\t\n132\t# 读取归档的顶层条目（第一个路径），用于从包内容识别真实版本——\n133\t# 不依赖文件名：现场投喂的包可能叫 tomcat.zip / tomcat-test.tar.gz 等任意名字。\n134\t# zip 优先用 unzip -Z1；目标机无 unzip 时用 python3 兜底（RPM 系 dnf 依赖 python3，几乎必装）。\n135\tarchive_top_entry() {\n136\t    local f=\"$1\"\n137\t    case \"${f}\" in\n138\t        *.zip)\n139\t            if have_cmd unzip; then\n140\t                unzip -Z1 \"${f}\" 2>/dev/null | grep -m1 -v '^$' || true\n141\t            elif have_cmd python3; then\n142\t                python3 -c 'import sys, zipfile\n143\tz = zipfile.ZipFile(sys.argv[1])\n144\tfor n in z.namelist():\n145\t    if n.strip():\n146\t        print(n)\n147\t        break' \"${f}\" 2>/dev/null || true\n148\t            fi\n149\t            ;;\n150\t        *.tar.gz|*.tgz)\n151\t            tar -tzf \"${f}\" 2>/dev/null | head -n1 || true\n152\t            ;;\n153\t        *) printf '' ;;\n154\t    esac\n155\t}\n156\t\n157\t# 寻找包目录中匹配 family+arch 的 rpm/deb\n158\tfind_package() {\n159\t    # 用法: find_package <family> <arch> <pattern>\n160\t    # 例: find_package rhel8-line x86_64 mysql-community-server\n161\t    local family=\"$1\" arch=\"$2\" pattern=\"$3\"\n162\t    local subdir=\"${family}/${arch}\"\n163\t    if [[ -d \"${PKG_DIR}/${subdir}\" ]]; then\n164\t        find \"${PKG_DIR}/${subdir}\" -maxdepth 1 -name \"${pattern}*\" \\( -name \"*.rpm\" -o -name \"*.deb\" -o -name \"*.tar.gz\" -o -name \"*.tar.xz\" \\) | head -n 20\n165\t    fi\n166\t}\n167\t\n168\t# yum/dnf 离线安装 RPM 目录\n169\trpm_install_local() {\n170\t    # 用法: rpm_install_local <family> <arch>\n171\t    local family=\"$1\" arch=\"$2\"\n172\t    local dir=\"${PKG_DIR}/${family}/${arch}/rpms\"\n173\t    [[ -d \"${dir}\" ]] || die \"${EX_DEPS}\" \"未找到 RPM 包目录：${dir}\"\n174\t    if have_cmd dnf; then\n175\t        run dnf -y --disablerepo='*' install \"${dir}\"/*.rpm\n176\t    elif have_cmd yum; then\n177\t        run yum -y --disablerepo='*' install \"${dir}\"/*.rpm\n178\t    elif have_cmd rpm; then\n179\t        run rpm -Uvh --nodeps --force \"${dir}\"/*.rpm\n180\t    else\n181\t        die \"${EX_DEPS}\" \"系统无 dnf/yum/rpm\"\n182\t    fi\n183\t}\n184\t\n185\t# dpkg 离线安装 deb 目录\n186\tdeb_install_local() {\n187\t    local family=\"$1\" arch=\"$2\"\n188\t    local dir=\"${PKG_DIR}/${family}/${arch}/debs\"\n189\t    [[ -d \"${dir}\" ]] || die \"${EX_DEPS}\" \"未找到 DEB 包目录：${dir}\"\n190\t    run dpkg -i \"${dir}\"/*.deb || run apt-get -y -f install\n191\t}\n192\t\n193\t# 提取 tar 包到目标目录\n194\ttar_extract() {\n195\t    # 用法: tar_extract <tarfile> <target_dir>\n196\t    local tarfile=\"$1\" target=\"$2\"\n197\t    [[ -f \"${tarfile}\" ]] || die \"${EX_DEPS}\" \"tar 包不存在：${tarfile}\"\n198\t    mkdir -p \"${target}\"\n199\t    run tar -xf \"${tarfile}\" -C \"${target}\" --strip-components=1\n200\t}\n201\t\n202\t# 确认端口未占用（TCP 监听）\n203\tport_in_use() {\n204\t    local port=\"$1\"\n205\t    if have_cmd ss; then\n206\t        ss -ltnH 2>/dev/null | awk '{print $4}' | grep -E \"[:.]${port}$\" >/dev/null\n207\t    elif have_cmd netstat; then\n208\t        netstat -ltn 2>/dev/null | awk '{print $4}' | grep -E \"[:.]${port}$\" >/dev/null\n209\t    elif have_cmd lsof; then\n210\t        lsof -iTCP:\"${port}\" -sTCP:LISTEN >/dev/null 2>&1\n211\t    else\n212\t        return 1\n213\t    fi\n214\t}\n215\t\n216\t# -----------------------------------------------------------------------------\n217\t# 探测结果字段读取助手\n218\t# -----------------------------------------------------------------------------\n219\tdet_get() {\n220\t    # 用法: det_get <key> ; 若 cache 不存在返回空\n221\t    [[ -f \"${DETECT_CACHE}\" ]] || { printf ''; return; }\n222\t    local val\n223\t    val=\"$(awk -F= -v k=\"$1\" '$1==k {sub(/^[^=]*=/,\"\"); print; exit}' \"${DETECT_CACHE}\")\"\n224\t    # 去除外层引号（cache 是 KEY=\"VALUE\" 格式）\n225\t    val=\"${val#\\\"}\"\n226\t    val=\"${val%\\\"}\"\n227\t    # 若值是空 / 全空白，规范化返回空\n228\t    if [[ -z \"${val}\" || ! \"${val}\" =~ [^[:space:]] ]]; then\n229\t        printf ''\n230\t    else\n231\t        printf '%s' \"${val}\"\n232\t    fi\n233\t}\n234\t\n235\tos_family()  { det_get OS_FAMILY; }\n236\tarch()       { det_get ARCH; }\n237\tos_id()      { det_get OS_ID; }\n238\tos_ver()     { det_get OS_VERSION; }\n239\tpkg_mgr()    { det_get PKG_MGR; }\n240\thave_systemd() { [[ \"$(det_get HAVE_SYSTEMD)\" == \"1\" ]]; }\n241\thave_selinux() { [[ \"$(det_get HAVE_SELINUX)\" == \"1\" ]]; }\n242\thave_apparmor() { [[ \"$(det_get HAVE_APPARMOR)\" == \"1\" ]]; }\n243\thave_firewalld() { [[ \"$(det_get HAVE_FIREWALLD)\" == \"1\" ]]; }\n244\thave_ufw()      { [[ \"$(det_get HAVE_UFW)\" == \"1\" ]]; }\n245\thave_iptables() { [[ \"$(det_get HAVE_IPTABLES)\" == \"1\" ]]; }\n246\t\n247\t# -----------------------------------------------------------------------------\n248\t# 自动检测（供 collect.sh / collect_*.sh 共用）\n249\t# -----------------------------------------------------------------------------\n250\tauto_detect_family() {\n251\t    if [[ -f /etc/os-release ]]; then\n252\t        # shellcheck disable=SC1091\n253\t        source /etc/os-release\n254\t        local id=\"${ID:-unknown}\"\n255\t        local ver=\"${VERSION_ID:-${VERSION:-}}\"\n256\t        case \"${id}:${ver}\" in\n257\t            rhel:7*|centos:7*|rocky:7*|almalinux:7*) echo \"rhel7-line\" ;;\n258\t            rhel:8*|centos:8*|rocky:8*|almalinux:8*) echo \"rhel8-line\" ;;\n259\t            rhel:9*|centos:9*|rocky:9*|almalinux:9*) echo \"rhel8-line\" ;;   # 9 系沿用 8-line 路径\n260\t            openEuler:20.03*)                         echo \"rhel7-line\" ;;  # glibc 2.28 但 rpmlib 类似 rhel7\n261\t            openEuler:22.03*|openEuler:24.03*)        echo \"openeuler-line\" ;;\n262\t            anolis:*|TencentOS:*|openCloudOS:*)        echo \"rhel8-line\" ;;\n263\t            kylin:*V10*|kylin:*v10*)                   echo \"rhel7-line\" ;;  # V10 SP1/SP2 glibc 2.17\n264\t            kylin:*V11*|kylin:*v11*)                   echo \"openeuler-line\" ;;\n265\t            ubuntu:*|debian:*|deepin:*|Kylin:*Desktop*) echo \"deb-line\" ;;\n266\t            # UOS 需要进一步探测\n267\t            UOS:*|uos:*)\n268\t                if command -v dpkg >/dev/null 2>&1 && dpkg -l >/dev/null 2>&1; then\n269\t                    echo \"deb-line\"\n270\t                else\n271\t                    echo \"rhel8-line\"\n272\t                fi\n273\t                ;;\n274\t            *) echo \"rhel8-line\" ;;  # 保守默认\n275\t        esac\n276\t    else\n277\t        echo \"rhel8-line\"\n278\t    fi\n279\t}\n280\t\n281\tauto_detect_arch() {\n282\t    uname -m\n283\t}\n284\t\n285\t# 根据 family 推导包管理器\n286\tdetect_pkg_mgr() {\n287\t    local fam=\"${1:-$(auto_detect_family)}\"\n288\t    case \"${fam}\" in\n289\t        rhel7-line)\n290\t            if have_cmd dnf; then echo \"dnf\"\n291\t            elif have_cmd yum; then echo \"yum\"\n292\t            else echo \"rpm\"\n293\t            fi ;;\n294\t        rhel8-line|openeuler-line)\n295\t            if have_cmd dnf; then echo \"dnf\"\n296\t            elif have_cmd yum; then echo \"yum\"\n297\t            else echo \"rpm\"\n298\t            fi ;;\n299\t        deb-line)\n300\t            if have_cmd apt-get; then echo \"apt-get\"\n301\t            else echo \"dpkg\"\n302\t            fi ;;\n303\t        *) echo \"rpm\" ;;\n304\t    esac\n305\t}\n306\t\n307\t# -----------------------------------------------------------------------------\n308\t# 公共 stage 入口模板\n309\t# -----------------------------------------------------------------------------\n310\tstage_begin() {\n311\t    info \"===== Stage: $* =====\"\n312\t}\n313\t\n314\tstage_end() {\n315\t    info \"===== Stage $* done =====\"\n316\t}"}